   { COL_SYSCW, "SYSCW", "SYSCW", "Number of write(2) syscalls for the process", 10, true },
   { COL_RBYTES, "RBYTES", "RBYTES", "Bytes of read(2) I/O for the process", 10, true },
   { COL_WBYTES, "WBYTES", "WBYTES", "Bytes of write(2) I/O for the process", 10, true },
