   { COL_IO_WRITE_RATE, "IO_WRITE_RATE", "DISK WRITE", "The I/O rate of write(2) in bytes per second for the process", 10, true },
   { COL_IO_RATE, "IO_RATE", "DISK R/W", "Total I/O rate in bytes per second", 10, true },
   { COL_CGROUP, "CGROUP", "CGROUP", "Which cgroup the process is in", 12, false },
   { COL_OOM, "OOM", "OOM", "OOM (Out-of-Memory) killer score", 4, true },
   { COL_IO_PRIORITY, "IO_PRIORITY", "IOPRI", "I/O priority", 5, false },
   { COL_M_PSS, "M_PSS", "PSS", "proportional set size, same as M_RESIDENT but each page is divided by the number of processes sharing it", 6, true },
   { COL_M_SWAP, "M_SWAP", "SWAP", "Size of the process's swapped pages", 6, true },
   { COL_M_PSSWP, "M_PSSWP", "PSSWP", "shows proportional swap share of this mapping, unlike \"Swap\", this does not take into account swapped out page of underlying shmem objects", 6, true },
   { COL_CTXT, "CTXT", "CTXT", "Context switches (incremental sum of voluntary_ctxt_switches and nonvoluntary_ctxt_switches)", 8, true },
   { COL_SECATTR, "SECATTR", "SECATTR", "Security attribute of the process (e.g. SELinux or AppArmor)", 10, false },
   { COL_COMM, "COMM", "COMM", "comm string of the process from /proc/[pid]/comm", 10, false },
   { COL_EXE, "EXE", "EXE", "Basename of exe of the process from /proc/[pid]/exe", 10, false },
   { COL_CWD, "CWD", "CWD", "The current working directory of the process", 10, false },
   { COL_AUTOGROUP_ID, "AUTOGROUP_ID", "AGID", "The autogroup identifier of the process", 6, true },
   { COL_AUTOGROUP_NICE, "AUTOGROUP_NICE", "ANI", "Nice value (the higher the value, the more other processes take priority) associated with the process autogroup", 3, true },
   { COL_CCGROUP, "CCGROUP", "CCGROUP", "Which cgroup the process is in (condensed to essentials)", 12, false },
   { COL_CONTAINER, "CONTAINER", "CONTAINER", "Name of the container the process is in (guessed by heuristics)", 10, false },
   { COL_M_PRIV, "M_PRIV", "PRIV", "The private memory size of the process - resident set size minus shared memory", 6, true },
   { COL_GPU_TIME, "GPU_TIME", "GTIME+", "Total GPU time", 8, true },
   { COL_GPU_PERCENT, "GPU_PERCENT", "GPU%", "Percentage of the GPU time the process used in the last sampling", 5, true },
   { COL_ISCONTAINER, "ISCONTAINER", "CONT", "Whether the process is running inside a child container", 4, false }
};

static const size_t NUM_COLUMNS = sizeof(COLUMNS) / sizeof(COLUMNS[0]);

const ColumnInfo* Column_getInfo(ColumnId id) {
   for (size_t i = 0; i < NUM_COLUMNS; i++) {
      if (COLUMNS[i].id == id) {
         return &COLUMNS[i];
      }
   }
   return NULL;
}

int Column_idFromName(const char* name) {
   if (!name) return -1;
   for (size_t i = 0; i < NUM_COLUMNS; i++) {
      if (strcmp(COLUMNS[i].name, name) == 0) {
         return (int)COLUMNS[i].id;
      }
   }
   return -1;
}

const char* Column_nameFromId(ColumnId id) {
   const ColumnInfo* info = Column_getInfo(id);
   return info ? info->name : NULL;
}
EOF"}

