#include "Settings.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <pwd.h>

Settings g_settings;

static void getHtoprcPath(char* path, size_t size) {
   const char* home = getenv("HOME");
   if (!home) {
      struct passwd* pw = getpwuid(getuid());
      if (pw) home = pw->pw_dir;
   }
   if (!home) home = "/tmp";
   snprintf(path, size, "%s/.config/htop/htoprc", home);
}

static void ensureConfigDirExists(void) {
   const char* home = getenv("HOME");
   if (!home) {
      struct passwd* pw = getpwuid(getuid());
      if (pw) home = pw->pw_dir;
   }
   if (!home) home = "/tmp";

   char dir[512];
   snprintf(dir, sizeof(dir), "%s/.config", home);
   mkdir(dir, 0755);
   snprintf(dir, sizeof(dir), "%s/.config/htop", home);
   mkdir(dir, 0755);
}

void Settings_init(void) {
   memset(&g_settings, 0, sizeof(Settings));
   g_settings.delay = 15;
   g_settings.color_scheme = 0;
   g_settings.enable_mouse = true;
   g_settings.hide_function_bar = false;
   g_settings.hide_kernel_threads = true;
   g_settings.hide_userland_threads = false;
   g_settings.tree_view = false;
   g_settings.sort_key = COL_PERCENT_CPU;
   g_settings.sort_direction = -1;
   g_settings.tree_sort_key = COL_PID;
   g_settings.tree_sort_direction = 1;
   g_settings.highlight_changes = false;
   g_settings.highlight_changes_delay_secs = 5;
   g_settings.highlight_threads = true;
   g_settings.show_thread_names = false;
   g_settings.show_program_path = true;
   g_settings.highlight_base_name = false;
   g_settings.highlight_megabytes = true;
   g_settings.header_margin = true;
   g_settings.screen_tabs = true;
   g_settings.detailed_cpu_time = false;
   g_settings.cpu_count_from_one = false;
   g_settings.show_cpu_usage = true;
   g_settings.show_cpu_frequency = false;
   g_settings.show_cached_memory = true;
   g_settings.update_process_names = false;
   g_settings.account_guest_in_cpu_meter = false;
   g_settings.readonly = false;
   g_settings.no_unicode = false;
   g_settings.no_meters = false;
   g_settings.filter[0] = '\0';
   g_settings.filter_user_active = false;
   g_settings.pid_list = NULL;
   g_settings.pid_list_count = 0;
   g_settings.max_iterations = 0;
   g_settings.active_tab = 0;
}

void Settings_save(void) {
   ensureConfigDirExists();
   char path[512];
   getHtoprcPath(path, sizeof(path));

   FILE* f = fopen(path, "w");
   if (!f) return;

   fprintf(f, "# Beware! This file is rewritten by htop when settings are changed in the interface.\n");
   fprintf(f, "# The parser is also very primitive, and not human-friendly.\n");
   fprintf(f, "htop_version=3.5.0-dev-76f3fce\n");
   fprintf(f, "config_reader_min_version=3\n");
   fprintf(f, "fields=0 48 17 18 38 39 40 2 46 47 49 1\n");
   fprintf(f, "hide_kernel_threads=%d\n", g_settings.hide_kernel_threads ? 1 : 0);
   fprintf(f, "hide_userland_threads=%d\n", g_settings.hide_userland_threads ? 1 : 0);
   fprintf(f, "hide_running_in_container=0\n");
   fprintf(f, "shadow_other_users=0\n");
   fprintf(f, "show_thread_names=%d\n", g_settings.show_thread_names ? 1 : 0);
   fprintf(f, "show_program_path=%d\n", g_settings.show_program_path ? 1 : 0);
   fprintf(f, "highlight_base_name=%d\n", g_settings.highlight_base_name ? 1 : 0);
   fprintf(f, "highlight_deleted_exe=1\n");
   fprintf(f, "shadow_distribution_path_prefix=0\n");
   fprintf(f, "highlight_megabytes=%d\n", g_settings.highlight_megabytes ? 1 : 0);
   fprintf(f, "highlight_threads=%d\n", g_settings.highlight_threads ? 1 : 0);
   fprintf(f, "highlight_changes=%d\n", g_settings.highlight_changes ? 1 : 0);
   fprintf(f, "highlight_changes_delay_secs=%d\n", g_settings.highlight_changes_delay_secs);
   fprintf(f, "find_comm_in_cmdline=1\n");
   fprintf(f, "strip_exe_from_cmdline=1\n");
   fprintf(f, "show_merged_command=0\n");
   fprintf(f, "header_margin=%d\n", g_settings.header_margin ? 1 : 0);
   fprintf(f, "screen_tabs=%d\n", g_settings.screen_tabs ? 1 : 0);
   fprintf(f, "detailed_cpu_time=%d\n", g_settings.detailed_cpu_time ? 1 : 0);
   fprintf(f, "cpu_count_from_one=%d\n", g_settings.cpu_count_from_one ? 1 : 0);
   fprintf(f, "show_cpu_usage=%d\n", g_settings.show_cpu_usage ? 1 : 0);
   fprintf(f, "show_cpu_frequency=%d\n", g_settings.show_cpu_frequency ? 1 : 0);
   fprintf(f, "show_cached_memory=%d\n", g_settings.show_cached_memory ? 1 : 0);
   fprintf(f, "update_process_names=%d\n", g_settings.update_process_names ? 1 : 0);
   fprintf(f, "account_guest_in_cpu_meter=%d\n", g_settings.account_guest_in_cpu_meter ? 1 : 0);
   fprintf(f, "color_scheme=%d\n", g_settings.color_scheme);
   fprintf(f, "enable_mouse=%d\n", g_settings.enable_mouse ? 1 : 0);
   fprintf(f, "delay=%d\n", g_settings.delay);
   fprintf(f, "hide_function_bar=%d\n", g_settings.hide_function_bar ? 1 : 0);
   fprintf(f, "header_layout=two_50_50\n");
   fprintf(f, "column_meters_0=LeftCPUs8 Memory Swap\n");
   fprintf(f, "column_meter_modes_0=1 1 1\n");
   fprintf(f, "column_meters_1=RightCPUs8 Tasks LoadAverage Uptime\n");
   fprintf(f, "column_meter_modes_1=1 2 2 2\n");
   fprintf(f, "tree_view=%d\n", g_settings.tree_view ? 1 : 0);
   fprintf(f, "sort_key=%d\n", (int)g_settings.sort_key);
   fprintf(f, "tree_sort_key=%d\n", (int)g_settings.tree_sort_key);
   fprintf(f, "sort_direction=%d\n", g_settings.sort_direction);
   fprintf(f, "tree_sort_direction=%d\n", g_settings.tree_sort_direction);
   fprintf(f, "tree_view_always_by_pid=0\n");
   fprintf(f, "all_branches_collapsed=0\n");
   fprintf(f, "screen:Main=PID USER PRIORITY NICE M_VIRT M_RESIDENT M_SHARE STATE PERCENT_CPU PERCENT_MEM TIME Command\n");
   fprintf(f, ".sort_key=%s\n", Column_nameFromId(g_settings.sort_key) ? Column_nameFromId(g_settings.sort_key) : "PERCENT_CPU");
   fprintf(f, ".tree_sort_key=%s\n", Column_nameFromId(g_settings.tree_sort_key) ? Column_nameFromId(g_settings.tree_sort_key) : "PID");
   fprintf(f, ".tree_view_always_by_pid=0\n");
   fprintf(f, ".tree_view=%d\n", g_settings.tree_view ? 1 : 0);
   fprintf(f, ".sort_direction=%d\n", g_settings.sort_direction);
   fprintf(f, ".tree_sort_direction=%d\n", g_settings.tree_sort_direction);
   fprintf(f, ".all_branches_collapsed=0\n");
   fprintf(f, "screen:I/O=PID USER IO_PRIORITY IO_RATE IO_READ_RATE IO_WRITE_RATE Command\n");
   fprintf(f, ".sort_key=IO_RATE\n");
   fprintf(f, ".tree_sort_key=PID\n");
   fprintf(f, ".tree_view_always_by_pid=0\n");
   fprintf(f, ".tree_view=0\n");
   fprintf(f, ".sort_direction=-1\n");
   fprintf(f, ".tree_sort_direction=1\n");
   fprintf(f, ".all_branches_collapsed=0\n");

   fclose(f);
}

void Settings_loadOrCreate(void) {
   char path[512];
   getHtoprcPath(path, sizeof(path));

   FILE* f = fopen(path, "r");
   if (!f) {
      Settings_save();
      return;
   }

   char line[256];
   while (fgets(line, sizeof(line), f)) {
      char key[128], val[128];
      if (sscanf(line, "%127[^=]=%127s", key, val) == 2) {
         if (strcmp(key, "delay") == 0) g_settings.delay = atoi(val);
         else if (strcmp(key, "color_scheme") == 0) g_settings.color_scheme = atoi(val);
         else if (strcmp(key, "enable_mouse") == 0) g_settings.enable_mouse = (atoi(val) != 0);
         else if (strcmp(key, "hide_function_bar") == 0) g_settings.hide_function_bar = (atoi(val) != 0);
         else if (strcmp(key, "hide_kernel_threads") == 0) g_settings.hide_kernel_threads = (atoi(val) != 0);
         else if (strcmp(key, "hide_userland_threads") == 0) g_settings.hide_userland_threads = (atoi(val) != 0);
         else if (strcmp(key, "tree_view") == 0) g_settings.tree_view = (atoi(val) != 0);
         else if (strcmp(key, "sort_key") == 0) g_settings.sort_key = (ColumnId)atoi(val);
         else if (strcmp(key, "sort_direction") == 0) g_settings.sort_direction = atoi(val);
         else if (strcmp(key, "highlight_changes") == 0) g_settings.highlight_changes = (atoi(val) != 0);
         else if (strcmp(key, "highlight_changes_delay_secs") == 0) g_settings.highlight_changes_delay_secs = atoi(val);
      }
   }
   fclose(f);
}
EOF"}

