#include "CommandLine.h"
#include "Settings.h"
#include "Columns.h"
#include "help_text.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <pwd.h>
#include <ctype.h>
#include <errno.h>

static bool isNumeric(const char* str) {
   if (!str || !*str) return false;
   if (*str == '+' || *str == '-') str++;
   if (!*str) return false;
   while (*str) {
      if (!isdigit((unsigned char)*str)) return false;
      str++;
   }
   return true;
}

int CommandLine_run(int argc, char** argv) {
   static const struct option long_options[] = {
      {"no-color", no_argument, NULL, 'C'},
      {"delay", required_argument, NULL, 'd'},
      {"filter", required_argument, NULL, 'F'},
      {"no-function-bar", no_argument, NULL, 1001},
      {"help", no_argument, NULL, 'h'},
      {"highlight-changes", optional_argument, NULL, 'H'},
      {"no-mouse", no_argument, NULL, 'M'},
      {"no-meters", no_argument, NULL, 1002},
      {"max-iterations", required_argument, NULL, 'n'},
      {"pid", required_argument, NULL, 'p'},
      {"readonly", no_argument, NULL, 1003},
      {"sort-key", required_argument, NULL, 's'},
      {"tree", no_argument, NULL, 't'},
      {"user", optional_argument, NULL, 'u'},
      {"no-unicode", no_argument, NULL, 'U'},
      {"version", no_argument, NULL, 'V'},
      {NULL, 0, NULL, 0}
   };

   opterr = 1; // enable standard getopt error messages for unrecognized options / missing arguments
   int opt;
   while ((opt = getopt_long(argc, argv, "Cd:F:hH::Mn:p:s:tu::UV", long_options, NULL)) != -1) {
      switch (opt) {
         case 'V':
            printf("htop 3.5.0-dev-76f3fce\n");
            exit(0);
         case 'h':
            printf("%s", HTOP_HELP_TEXT);
            exit(0);
         case 'C':
            g_settings.color_scheme = 1; // monochrome
            break;
         case 'd': {
            char* endptr;
            errno = 0;
            double val = strtod(optarg, &endptr);
            if (errno != 0 || *endptr != '\0') {
               fprintf(stderr, "Error: invalid delay value \"%s\".\n", optarg);
               exit(1);
            }
            g_settings.delay = (int)(val);
            break;
         }
         case 'F':
            strncpy(g_settings.filter, optarg, sizeof(g_settings.filter) - 1);
            g_settings.filter[sizeof(g_settings.filter) - 1] = '\0';
            break;
         case 1001: // --no-function-bar
            g_settings.hide_function_bar = true;
            break;
         case 'H': {
            const char* arg = optarg;
            if (!arg && optind < argc && argv[optind] && argv[optind][0] != '-') {
               arg = argv[optind++];
            }
            if (arg) {
               char* endptr;
               long val = strtol(arg, &endptr, 10);
               if (*endptr != '\0') {
                  fprintf(stderr, "Error: invalid highlight delay value \"%s\".\n", arg);
                  exit(1);
               }
               g_settings.highlight_changes_delay_secs = (int)val;
            }
            g_settings.highlight_changes = true;
            break;
         }
         case 'M':
            g_settings.enable_mouse = false;
            break;
         case 1002: // --no-meters
            g_settings.no_meters = true;
            break;
         case 'n': {
            char* endptr;
            long val = strtol(optarg, &endptr, 10);
            if (*endptr != '\0') {
               fprintf(stderr, "Error: invalid maximum iteration count \"%s\".\n", optarg);
               exit(1);
            }
            if (val <= 0) {
               fprintf(stderr, "Error: maximum iteration count must be positive.\n");
               exit(1);
            }
            g_settings.max_iterations = (int)val;
            break;
         }
         case 'p': {
            // comma-separated pids
            char* copy = strdup(optarg);
            char* token = strtok(copy, ",");
            while (token) {
               if (isNumeric(token)) {
                  int p = atoi(token);
                  g_settings.pid_list = realloc(g_settings.pid_list, sizeof(pid_t) * (g_settings.pid_list_count + 1));
                  g_settings.pid_list[g_settings.pid_list_count++] = p;
               }
               token = strtok(NULL, ",");
            }
            free(copy);
            break;
         }
         case 1003: // --readonly
            g_settings.readonly = true;
            break;
         case 's': {
            if (strcmp(optarg, "help") == 0) {
               printf("%s", HTOP_SORT_HELP_TEXT);
               exit(0);
            }
            int colId = Column_idFromName(optarg);
