{"command":"cat << 'EOF' > src/SysInfo.c
#include "SysInfo.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

SysInfo g_sysInfo;

void SysInfo_init(void) {
   memset(&g_sysInfo, 0, sizeof(SysInfo));
   long nprocs = sysconf(_SC_NPROCESSORS_ONLN);
   if (nprocs < 1) nprocs = 1;
   g_sysInfo.cpuCount = (int)nprocs;
   g_sysInfo.cpus = calloc(g_sysInfo.cpuCount, sizeof(CPUData));
}

void SysInfo_free(void) {
   if (g_sysInfo.cpus) {
      free(g_sysInfo.cpus);
      g_sysInfo.cpus = NULL;
   }
}

static void readMemInfo(void) {
   FILE* f = fopen("/proc/meminfo", "r");
   if (!f) return;

   char line[128];
   unsigned long long memTotal = 0, memFree = 0, buffers = 0, cached = 0, SReclaimable = 0;
   unsigned long long swapTotal = 0, swapFree = 0;

   while (fgets(line, sizeof(line), f)) {
      if (sscanf(line, "MemTotal: %llu kB", &memTotal) == 1) continue;
      if (sscanf(line, "MemFree: %llu kB", &memFree) == 1) continue;
      if (sscanf(line, "Buffers: %llu kB", &buffers) == 1) continue;
      if (sscanf(line, "Cached: %llu kB", &cached) == 1) continue;
      if (sscanf(line, "SReclaimable: %llu kB", &SReclaimable) == 1) continue;
      if (sscanf(line, "SwapTotal: %llu kB", &swapTotal) == 1) continue;
      if (sscanf(line, "SwapFree: %llu kB", &swapFree) == 1) continue;
   }
   fclose(f);

   g_sysInfo.totalMem = memTotal * 1024;
   g_sysInfo.freeMem = memFree * 1024;
   g_sysInfo.buffersMem = buffers * 1024;
   g_sysInfo.cachedMem = (cached + SReclaimable) * 1024;

   if (memTotal > (memFree + buffers + cached + SReclaimable)) {
      g_sysInfo.usedMem = (memTotal - memFree - buffers - cached - SReclaimable) * 1024;
   } else {
      g_sysInfo.usedMem = 0;
   }

   g_sysInfo.totalSwap = swapTotal * 1024;
   g_sysInfo.freeSwap = swapFree * 1024;
   g_sysInfo.usedSwap = (swapTotal >= swapFree) ? (swapTotal - swapFree) * 1024 : 0;
}

static void readCPUInfo(void) {
   FILE* f = fopen("/proc/stat", "r");
   if (!f) return;

   char line[256];
   while (fgets(line, sizeof(line), f)) {
      if (strncmp(line, "cpu ", 4) == 0) {
         unsigned long long u, n, s, i, io, ir, sir, st, g;
         if (sscanf(line + 4, "%llu %llu %llu %llu %llu %llu %llu %llu %llu",
                    &u, &n, &s, &i, &io, &ir, &sir, &st, &g) >= 4) {
            unsigned long long tot = u + n + s + i + io + ir + sir + st;
            unsigned long long idle_time = i + io;
            if (g_sysInfo.totalCPU.total > 0 && tot > g_sysInfo.totalCPU.total) {
               unsigned long long diff_tot = tot - g_sysInfo.totalCPU.total;
               unsigned long long diff_idle = idle_time - (g_sysInfo.totalCPU.idle + g_sysInfo.totalCPU.iowait);
               if (diff_tot > 0 && diff_tot >= diff_idle) {
                  g_sysInfo.totalCPU.percent = (double)(diff_tot - diff_idle) * 100.0 / (double)diff_tot;
               }
            }
