{"command":"cat << 'EOF' > src/Process.c
#include "Process.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void formatMemory(unsigned long long bytes, char* buf, size_t size) {
   if (bytes < 1024ULL * 1024ULL) {
      snprintf(buf, size, "%lluK", bytes / 1024ULL);
   } else if (bytes < 1024ULL * 1024ULL * 1024ULL) {
      snprintf(buf, size, "%lluM", bytes / (1024ULL * 1024ULL));
   } else if (bytes < 1024ULL * 1024ULL * 1024ULL * 1024ULL) {
      snprintf(buf, size, "%.2fG", (double)bytes / (1024.0 * 1024.0 * 1024.0));
   } else {
      snprintf(buf, size, "%.2fT", (double)bytes / (1024.0 * 1024.0 * 1024.0 * 1024.0));
   }
}

static void formatTime(unsigned long long time_ms, char* buf, size_t size) {
   unsigned long long total_sec = time_ms / 1000;
   unsigned int ms_hundredths = (time_ms % 1000) / 10;
   unsigned int sec = total_sec % 60;
   unsigned int min = (total_sec / 60) % 60;
   unsigned int hrs = total_sec / 3600;

   if (hrs > 0) {
      snprintf(buf, size, "%u:%02u:%02u", hrs, min, sec);
   } else {
      snprintf(buf, size, "%u:%02u.%02u", min, sec, ms_hundredths);
   }
}

static void formatRate(double bytes_per_sec, char* buf, size_t size) {
   if (bytes_per_sec < 1024.0) {
      snprintf(buf, size, "%.0f B/s", bytes_per_sec);
   } else if (bytes_per_sec < 1024.0 * 1024.0) {
      snprintf(buf, size, "%.1f K/s", bytes_per_sec / 1024.0);
   } else if (bytes_per_sec < 1024.0 * 1024.0 * 1024.0) {
      snprintf(buf, size, "%.1f M/s", bytes_per_sec / (1024.0 * 1024.0));
   } else {
      snprintf(buf, size, "%.1f G/s", bytes_per_sec / (1024.0 * 1024.0 * 1024.0));
   }
}

Process* Process_new(pid_t pid) {
   Process* p = calloc(1, sizeof(Process));
   p->pid = pid;
   strcpy(p->io_priority, "none");
   return p;
}

void Process_delete(Process* p) {
   if (!p) return;
   if (p->cmdline) free(p->cmdline);
   if (p->children) free(p->children);
   free(p);
}

void Process_formatField(const Process* p, ColumnId col, char* buf, size_t size) {
   if (!p || !buf || size == 0) return;
   buf[0] = '\0';

   switch (col) {
      case COL_PID:
         snprintf(buf, size, "%6d", p->pid);
         break;
      case COL_USER:
         snprintf(buf, size, "%-9.9s", p->user[0] ? p->user : "root");
         break;
      case COL_PRIORITY:
         if (p->priority < -100) snprintf(buf, size, " RT");
         else snprintf(buf, size, "%3d", p->priority);
         break;
      case COL_NICE:
         snprintf(buf, size, "%3d", p->nice);
         break;
      case COL_M_VIRT:
         formatMemory(p->m_virt, buf, size);
         break;
      case COL_M_RESIDENT:
         formatMemory(p->m_resident, buf, size);
         break;
      case COL_M_SHARE:
         formatMemory(p->m_share, buf, size);
         break;
      case COL_STATE:
         snprintf(buf, size, "%c", p->state ? p->state : 'S');
         break;
      case COL_PERCENT_CPU:
         snprintf(buf, size, "%5.1f", p->percent_cpu);
         break;
      case COL_PERCENT_MEM:
         snprintf(buf, size, "%4.1f", p->percent_mem);
         break;
      case COL_TIME:
         formatTime(p->time_ms, buf, size);
         break;
      case COL_COMMAND:
         snprintf(buf, size, "%s", (p->cmdline && p->cmdline[0]) ? p->cmdline : p->comm);
         break;
      case COL_PPID:
         snprintf(buf, size, "%6d", p->ppid);
         break;
      case COL_PGRP:
         snprintf(buf, size, "%6d", p->pgrp);
         break;
      case COL_SESSION:
         snprintf(buf, size, "%6d", p->session);
         break;
