#include "ProcessList.h"
#include "Settings.h"
#include "SysInfo.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <pwd.h>
#include <ctype.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>

ProcessList g_processList;

void ProcessList_init(void) {
   memset(&g_processList, 0, sizeof(ProcessList));
}

void ProcessList_free(void) {
   for (int i = 0; i < g_processList.count; i++) {
      Process_delete(g_processList.processes[i]);
   }
   if (g_processList.processes) free(g_processList.processes);
   if (g_processList.display_processes) free(g_processList.display_processes);
   memset(&g_processList, 0, sizeof(ProcessList));
}

static Process* findOrCreateProcess(pid_t pid) {
   for (int i = 0; i < g_processList.count; i++) {
      if (g_processList.processes[i]->pid == pid) {
         return g_processList.processes[i];
      }
   }
   Process* p = Process_new(pid);
   if (g_processList.count >= g_processList.capacity) {
      g_processList.capacity = (g_processList.capacity == 0) ? 64 : g_processList.capacity * 2;
      g_processList.processes = realloc(g_processList.processes, sizeof(Process*) * g_processList.capacity);
   }
   g_processList.processes[g_processList.count++] = p;
   return p;
}

static void readProcessStat(Process* p) {
   char path[256];
   snprintf(path, sizeof(path), "/proc/%d/stat", p->pid);
   FILE* f = fopen(path, "r");
   if (!f) return;

   char buf[1024];
   if (!fgets(buf, sizeof(buf), f)) {
      fclose(f);
      return;
   }
   fclose(f);

   char* open_paren = strchr(buf, '(');
   char* close_paren = strrchr(buf, ')');
   if (!open_paren || !close_paren || close_paren <= open_paren) return;

   size_t comm_len = close_paren - open_paren - 1;
   if (comm_len >= sizeof(p->comm)) comm_len = sizeof(p->comm) - 1;
   strncpy(p->comm, open_paren + 1, comm_len);
   p->comm[comm_len] = '\0';

   char* rest = close_paren + 2;
   char state;
   int ppid, pgrp, session, tty_nr, tpgid, flags, priority, nice, num_threads, processor;
   unsigned long minflt, cminflt, majflt, cmajflt;
   unsigned long long utime, stime, cutime, cstime, starttime, vsize, rss;

   if (sscanf(rest, "%c %d %d %d %d %d %d %lu %lu %lu %lu %llu %llu %llu %llu %d %d %d %*d %llu %llu %llu %*u %*u %*u %*u %*u %*u %*u %*u %*u %*u %*u %*u %*u %*u %d",
              &state, &ppid, &pgrp, &session, &tty_nr, &tpgid, &flags,
              &minflt, &cminflt, &majflt, &cmajflt,
              &utime, &stime, &cutime, &cstime,
              &priority, &nice, &num_threads, &starttime,
              &vsize, &rss, &processor) >= 19) {
      p->state = state;
      p->ppid = ppid;
      p->pgrp = pgrp;
      p->session = session;
      p->tty_nr = tty_nr;
      p->tpgid = tpgid;
      p->minflt = minflt;
      p->cminflt = cminflt;
      p->majflt = majflt;
      p->cmajflt = cmajflt;
      p->utime = utime;
      p->stime = stime;
      p->cutime = cutime;
      p->cstime = cstime;
      p->priority = priority;
      p->nice = nice;
      p->num_threads = num_threads;
      p->starttime = starttime;
      p->m_virt = vsize;
      p->m_resident = rss * 4096ULL;
      p->processor = processor;

      p->time_ms = (utime + stime) * 10ULL; // 100 Hz jiffies -> ms
      p->is_kernel_thread = (vsize == 0 || ppid == 2 || (p->comm[0] == '[' && p->comm[strlen(p->comm)-1] == ']'));
   }
}

static void readProcessStatm(Process* p) {
   char path[256];
   snprintf(path, sizeof(path), "/proc/%d/statm", p->pid);
   FILE* f = fopen(path, "r");
   if (!f) return;

   unsigned long long size, resident, share, trs, lrs, drs;
   if (fscanf(f, "%llu %llu %llu %llu %llu %llu", &size, &resident, &share, &trs, &lrs, &drs) == 6) {
      p->m_virt = size * 4096ULL;
      p->m_resident = resident * 4096ULL;
      p->m_share = share * 4096ULL;
      p->m_trs = trs * 4096ULL;
      p->m_drs = drs * 4096ULL;
      p->m_lrs = lrs * 4096ULL;
   }
   fclose(f);
}

static void readProcessCmdline(Process* p) {
   char path[256];
   snprintf(path, sizeof(path), "/proc/%d/cmdline", p->pid);
   int fd = open(path, O_RDONLY);
   if (fd < 0) return;

   char buf[4096];
   ssize_t n = read(fd, buf, sizeof(buf) - 1);
   close(fd);

   if (n > 0) {
      buf[n] = '\0';
