   snprintf(path, sizeof(path), "/proc/%d/io", p->pid);
   FILE* f = fopen(path, "r");
   if (!f) return;

   char line[256];
   while (fgets(line, sizeof(line), f)) {
      if (sscanf(line, "rchar: %llu", &p->io_rchar) == 1) continue;
      if (sscanf(line, "wchar: %llu", &p->io_wchar) == 1) continue;
      if (sscanf(line, "syscr: %llu", &p->io_syscr) == 1) continue;
      if (sscanf(line, "syscw: %llu", &p->io_syscw) == 1) continue;
      if (sscanf(line, "read_bytes: %llu", &p->io_read_bytes) == 1) continue;
      if (sscanf(line, "write_bytes: %llu", &p->io_write_bytes) == 1) continue;
   }
   fclose(f);
}

void ProcessList_scan(void) {
   for (int i = 0; i < g_processList.count; i++) {
      g_processList.processes[i]->updated = false;
   }

   DIR* dir = opendir("/proc");
   if (!dir) return;

   struct dirent* entry;
   while ((entry = readdir(dir)) != NULL) {
      if (entry->d_type == DT_DIR || entry->d_type == DT_UNKNOWN) {
         if (isdigit((unsigned char)entry->d_name[0])) {
            pid_t pid = atoi(entry->d_name);
            if (pid > 0) {
               Process* p = findOrCreateProcess(pid);
               p->updated = true;
               readProcessStat(p);
               readProcessStatm(p);
               readProcessCmdline(p);
               readProcessStatus(p);
               readProcessIO(p);

               // Calculate CPU %
               unsigned long long cur_utime_stime = p->utime + p->stime;
               if (p->last_utime_stime > 0 && cur_utime_stime >= p->last_utime_stime) {
                  unsigned long long diff = cur_utime_stime - p->last_utime_stime;
                  // Assuming 1 second sampling or scale by total CPU delta
                  p->percent_cpu = (double)diff * 100.0 / 100.0; // jiffies / 100
                  if (p->percent_cpu > 100.0 * g_sysInfo.cpuCount) {
                     p->percent_cpu = 100.0 * g_sysInfo.cpuCount;
                  }
               } else {
                  p->percent_cpu = 0.0;
               }
               p->last_utime_stime = cur_utime_stime;

               // Calculate MEM %
               if (g_sysInfo.totalMem > 0) {
                  p->percent_mem = (double)p->m_resident * 100.0 / (double)g_sysInfo.totalMem;
               } else {
                  p->percent_mem = 0.0;
               }
            }
         }
      }
   }
   closedir(dir);

   // Remove processes that no longer exist
   int writeIdx = 0;
   for (int i = 0; i < g_processList.count; i++) {
      if (g_processList.processes[i]->updated) {
         g_processList.processes[writeIdx++] = g_processList.processes[i];
      } else {
         Process_delete(g_processList.processes[i]);
      }
   }
   g_processList.count = writeIdx;

   ProcessList_sort();
}

static int compareProcessPtr(const void* a, const void* b) {
   const Process* p1 = *(const Process**)a;
   const Process* p2 = *(const Process**)b;
   return Process_compare(p1, p2, g_settings.sort_key, g_settings.sort_direction);
}

void ProcessList_sort(void) {
   if (g_processList.display_processes) {
      free(g_processList.display_processes);
      g_processList.display_processes = NULL;
   }
   g_processList.display_count = 0;

   // Filter
   Process** filtered = malloc(sizeof(Process*) * g_processList.count);
   int filtered_count = 0;

   for (int i = 0; i < g_processList.count; i++) {
      Process* p = g_processList.processes[i];

      if (g_settings.hide_kernel_threads && p->is_kernel_thread) continue;
      if (g_settings.hide_userland_threads && p->is_user_thread) continue;
      if (g_settings.filter_user_active && p->uid != g_settings.filter_user_uid) continue;

      if (g_settings.pid_list_count > 0) {
         bool matched = false;
         for (int k = 0; k < g_settings.pid_list_count; k++) {
            if (p->pid == g_settings.pid_list[k]) {
               matched = true;
               break;
            }
         }
         if (!matched) continue;
      }

      if (g_settings.filter[0] != '\0') {
         if (!strstr(p->comm, g_settings.filter) &&
             (!p->cmdline || !strstr(p->cmdline, g_settings.filter))) {
            continue;
         }
      }

      filtered[filtered_count++] = p;
   }

   qsort(filtered, filtered_count, sizeof(Process*), compareProcessPtr);

   g_processList.display_processes = filtered;
   g_processList.display_count = filtered_count;
}
EOF"}

