      case 'h':
      case '?':
         showHelpPopup();
         break;

      case KEY_F(3):
      case '/':
         in_search_mode = true;
         search_buf[0] = '\0';
         break;

      case KEY_F(4):
      case '\\':
         in_filter_mode = true;
