#include "ProcessList.h"
#include "UI.h"
#include <curses.h>
#include <signal.h>
#include <stdlib.h>
#include <unistd.h>

static void handleSigwinch(int sig) {
   (void)sig;
   endwin();
   refresh();
}

int main(int argc, char** argv) {
   Settings_init();
   Settings_loadOrCreate();
   CommandLine_run(argc, argv);

   SysInfo_init();
   ProcessList_init();

   signal(SIGWINCH, handleSigwinch);

   UI_init();

   int iterations = 0;
   bool should_exit = false;

   while (!should_exit) {
      SysInfo_update();
      ProcessList_scan();

      UI_draw();

      int key = getch();
      if (key != ERR) {
         if (UI_handleKey(key)) {
            should_exit = true;
         }
      }

      iterations++;
      if (g_settings.max_iterations > 0 && iterations >= g_settings.max_iterations) {
         break;
      }
   }

   UI_cleanup();
   ProcessList_free();
   SysInfo_free();

   return 0;
}
EOF"}

