   COLOR_DEFAULT = 1,
   COLOR_HEADER,
   COLOR_HIGHLIGHT,
   COLOR_SELECTION,
   COLOR_BAR_GREEN,
   COLOR_BAR_BLUE,
   COLOR_BAR_RED,
   COLOR_BAR_YELLOW,
   COLOR_METER_TEXT,
   COLOR_FUNCTION_BAR
