   y++;

   mvprintw(y, 2, "Swp[                     0K/0K]");
   mvprintw(y, 40, "Load average: %.2f %.2f %.2f",
            g_sysInfo.load1, g_sysInfo.load5, g_sysInfo.load15);
   y++;

   unsigned long uptime_sec = (unsigned long)g_sysInfo.uptime;
   unsigned long days = uptime_sec / 86400;
   unsigned long hours = (uptime_sec % 86400) / 3600;
   unsigned long mins = (uptime_sec % 3600) / 60;
   unsigned long secs = uptime_sec % 60;

   if (days > 0) {
      mvprintw(y, 40, "Uptime: %lu day%s, %02lu:%02lu:%02lu", days, days > 1 ? "s" : "", hours, mins, secs);
   } else {
      mvprintw(y, 40, "Uptime: %02lu:%02lu:%02lu", hours, mins, secs);
   }
   y++;

   y++; // blank row
   *next_y = y;
}

static void drawTabs(int y, int max_x) {
   (void)max_x;
   if (g_settings.active_tab == 0) {
      attron(A_REVERSE);
      mvaddstr(y, 2, " [Main] ");
      attroff(A_REVERSE);
      mvaddstr(y, 11, " [I/O] ");
   } else {
      mvaddstr(y, 2, " [Main] ");
      attron(A_REVERSE);
      mvaddstr(y, 11, " [I/O] ");
      attroff(A_REVERSE);
   }
}

static void drawTableHeader(int y, int max_x) {
   (void)max_x;
   move(y, 0);
   clrtoeol();
   attron(A_REVERSE);

   if (g_settings.active_tab == 0) {
      mvaddstr(y, 0, "  PID USER       PRI  NI  VIRT   RES   SHR S  CPU% MEM%   TIME+  Command");
   } else {
      mvaddstr(y, 0, "  PID USER       IOPRI IO_RATE     DISK READ  DISK WRITE Command");
   }

   attroff(A_REVERSE);
}

static void drawProcessList(int start_y, int max_y, int max_x) {
   (void)max_x;
   int list_height = max_y - start_y - 1;
   if (list_height < 1) return;

   int total = g_processList.display_count;
   if (selected_idx >= total) selected_idx = total - 1;
   if (selected_idx < 0) selected_idx = 0;

   if (selected_idx < scroll_offset) scroll_offset = selected_idx;
   if (selected_idx >= scroll_offset + list_height) scroll_offset = selected_idx - list_height + 1;

   for (int i = 0; i < list_height; i++) {
      int idx = scroll_offset + i;
      int cur_y = start_y + i;
      move(cur_y, 0);
      clrtoeol();

      if (idx < total) {
         Process* p = g_processList.display_processes[idx];
         bool is_selected = (idx == selected_idx);

         if (is_selected) attron(A_REVERSE);

         char linebuf[2048];
         if (g_settings.active_tab == 0) {
            char virt[16], res[16], shr[16], time_str[16];
            Process_formatField(p, COL_M_VIRT, virt, sizeof(virt));
            Process_formatField(p, COL_M_RESIDENT, res, sizeof(res));
            Process_formatField(p, COL_M_SHARE, shr, sizeof(shr));
            Process_formatField(p, COL_TIME, time_str, sizeof(time_str));

            snprintf(linebuf, sizeof(linebuf), "%6d %-9.9s %3d %3d %6s %6s %6s %c %5.1f %4.1f %8s %s",
                     p->pid, p->user[0] ? p->user : "root",
                     p->priority, p->nice, virt, res, shr,
                     p->state ? p->state : 'S',
                     p->percent_cpu, p->percent_mem, time_str,
                     (p->cmdline && p->cmdline[0]) ? p->cmdline : p->comm);
         } else {
            snprintf(linebuf, sizeof(linebuf), "%6d %-9.9s %-5s %10s %10s %10s %s",
                     p->pid, p->user[0] ? p->user : "root",
                     p->io_priority, "0 B/s", "0 B/s", "0 B/s",
                     (p->cmdline && p->cmdline[0]) ? p->cmdline : p->comm);
         }

         mvaddstr(cur_y, 0, linebuf);

         if (is_selected) attroff(A_REVERSE);
      }
   }
}

static void drawFunctionBar(int max_y, int max_x) {
   if (g_settings.hide_function_bar) return;

   int y = max_y - 1;
   move(y, 0);
   clrtoeol();

   if (in_search_mode) {
      mvprintw(y, 0, "Search: %s_", search_buf);
   } else if (in_filter_mode) {
      mvprintw(y, 0, "Filter: %s_", filter_buf);
   } else {
      const char* fn_keys[] = {
         "F1Help", "F2Setup", "F3Search", "F4Filter", "F5Tree",
         "F6SortBy", "F7Nice -", "F8Nice +", "F9Kill", "F10Quit"
      };
      int x = 0;
      for (int i = 0; i < 10; i++) {
         mvaddstr(y, x, fn_keys[i]);
         x += (int)strlen(fn_keys[i]) + 2;
         if (x >= max_x) break;
      }
   }
}

void UI_draw(void) {
   int max_y, max_x;
   getmaxyx(stdscr, max_y, max_x);

   erase();

   int next_y = 0;
   drawHeaderMeters(max_y, max_x, &next_y);
   drawTabs(next_y, max_x);
   next_y++;
   drawTableHeader(next_y, max_x);
   next_y++;
   drawProcessList(next_y, max_y, max_x);
   drawFunctionBar(max_y, max_x);

   refresh();
}

static void showHelpPopup(void) {
   int max_y, max_x;
   getmaxyx(stdscr, max_y, max_x);

   WINDOW* win = newwin(max_y - 4, max_x - 10, 2, 5);
   box(win, 0, 0);
   mvwaddstr(win, 1, 2, "Help for htop 3.5.0-dev");
   mvwaddstr(win, 3, 2, "Press Esc or 'q' to close help.");
   mvwaddstr(win, 5, 2, "Navigation: Up/Down/PgUp/PgDn");
   mvwaddstr(win, 6, 2, "Search: / or F3");
   mvwaddstr(win, 7, 2, "Filter: \\ or F4");
   mvwaddstr(win, 8, 2, "Kill: k or F9");
   mvwaddstr(win, 9, 2, "Quit: q or F10");
   wrefresh(win);

   int ch;
   while ((ch = wgetch(win)) != ERR) {
      if (ch == 27 || ch == 'q' || ch == 'Q' || ch == KEY_F(1)) break;
   }
   delwin(win);
}

bool UI_handleKey(int key) {
   if (key == ERR) return false;

   if (in_search_mode) {
      if (key == 27 || key == '\n' || key == KEY_ENTER) {
         in_search_mode = false;
      } else if (key == KEY_BACKSPACE || key == 127 || key == 8) {
         size_t len = strlen(search_buf);
         if (len > 0) search_buf[len - 1] = '\0';
      } else if (key >= 32 && key <= 126) {
         size_t len = strlen(search_buf);
         if (len < sizeof(search_buf) - 1) {
            search_buf[len] = (char)key;
            search_buf[len + 1] = '\0';
         }
      }
      return false;
   }

   if (in_filter_mode) {
      if (key == 27 || key == '\n' || key == KEY_ENTER) {
         in_filter_mode = false;
         strncpy(g_settings.filter, filter_buf, sizeof(g_settings.filter) - 1);
         ProcessList_sort();
      } else if (key == KEY_BACKSPACE || key == 127 || key == 8) {
         size_t len = strlen(filter_buf);
         if (len > 0) filter_buf[len - 1] = '\0';
      } else if (key >= 32 && key <= 126) {
         size_t len = strlen(filter_buf);
         if (len < sizeof(filter_buf) - 1) {
            filter_buf[len] = (char)key;
            filter_buf[len + 1] = '\0';
         }
      }
      return false;
   }

   switch (key) {
      case 'q':
      case 'Q':
      case KEY_F(10):
         return true;

      case KEY_UP:
      case 'k':
         if (selected_idx > 0) selected_idx--;
         break;

      case KEY_DOWN:
      case 'j':
         if (selected_idx < g_processList.display_count - 1) selected_idx++;
         break;

      case KEY_PPAGE:
         selected_idx -= 10;
         if (selected_idx < 0) selected_idx = 0;
         break;

      case KEY_NPAGE:
         selected_idx += 10;
         if (selected_idx >= g_processList.display_count) selected_idx = g_processList.display_count - 1;
         break;

      case KEY_HOME:
         selected_idx = 0;
         break;

      case KEY_END:
         selected_idx = g_processList.display_count - 1;
         break;

      case '\t':
         g_settings.active_tab = (g_settings.active_tab == 0) ? 1 : 0;
         break;

      case KEY_F(1):
      case 'h':
      case '?':
         showHelpPopup();
         break;

      case KEY_F(3):
      case '/':
         in_search_mode = true;
         search_buf[0] = '\0';
         break;

      case KEY_F(4):
      case '\\':
         in_filter_mode = true;
         filter_buf[0] = '\0';
         break;

      case KEY_F(5):
      case 't':
         g_settings.tree_view = !g_settings.tree_view;
         ProcessList_sort();
         break;

      case KEY_F(9):
      case 'K':
         if (selected_idx >= 0 && selected_idx < g_processList.display_count) {
            Process* p = g_processList.display_processes[selected_idx];
            if (p && !g_settings.readonly) {
               kill(p->pid, SIGTERM);
            }
         }
         break;

      default:
         break;
   }

   return false;
}
